<?php
namespace Joomla\Component\Academy\Administrator\Controller;
defined('_JEXEC') or die;
use Joomla\CMS\Component\ComponentHelper;use Joomla\CMS\Factory;use Joomla\CMS\MVC\Controller\BaseController;use Joomla\CMS\Router\Route;use Joomla\CMS\Session\Session;use Joomla\CMS\Uri\Uri;use Joomla\Component\Academy\Administrator\Service\CampaignMailer;use Joomla\Database\DatabaseInterface;
final class NewsletterController extends BaseController
{
private function allowed():void{if(!Factory::getApplication()->getIdentity()->authorise('core.manage','com_academy'))throw new \RuntimeException('Not authorised',403);}
private function redirectToCampaign(int $campaignId=0):void{Factory::getApplication()->redirect(Route::_($campaignId?'index.php?option=com_academy&view=campaign&id='.$campaignId:'index.php?option=com_academy&view=newsletter',false));}
public function redirect($campaignId=0):void{$this->redirectToCampaign((int)$campaignId);}
public function queue():void{Session::checkToken()or jexit('Invalid token');$this->allowed();$app=Factory::getApplication();$subject=trim($app->getInput()->post->getString('subject'));$body=$app->getInput()->post->get('body','','raw');if($subject===''||trim(strip_tags($body))==='')throw new \RuntimeException('Subject and message are required.',400);$db=Factory::getContainer()->get(DatabaseInterface::class);$segment=$app->getInput()->post->getCmd('segment','all');if(!in_array($segment,['all','recent30','recent90'],true))$segment='all';$scheduleInput=$app->getInput()->post->getString('scheduled_at');$scheduledAt=$scheduleInput!==''?Factory::getDate($scheduleInput,$app->get('offset'))->toSql():null;$campaignState=$scheduledAt&&strtotime($scheduledAt)>time()?2:0;$campaign=(object)['subject'=>$subject,'body'=>$body,'state'=>$campaignState,'segment'=>$segment,'scheduled_at'=>$scheduledAt,'created'=>Factory::getDate()->toSql(),'created_by'=>(int)$app->getIdentity()->id];$db->insertObject('#__academy_campaigns',$campaign,'id');if($app->getInput()->post->getInt('save_template')){$template=(object)['title'=>$app->getInput()->post->getString('template_title')?:$subject,'subject'=>$subject,'body'=>$body,'created'=>Factory::getDate()->toSql()];$db->insertObject('#__academy_email_templates',$template);}$subscriberQuery=$db->createQuery()->select(['id','name','email','token'])->from('#__academy_subscribers')->where('state=1');if($segment==='recent30')$subscriberQuery->where('consented >= DATE_SUB(NOW(), INTERVAL 30 DAY)');if($segment==='recent90')$subscriberQuery->where('consented >= DATE_SUB(NOW(), INTERVAL 90 DAY)');$subscribers=$db->setQuery($subscriberQuery)->loadObjectList();foreach($subscribers as $subscriber){$queue=(object)['campaign_id'=>(int)$campaign->id,'subscriber_id'=>(int)$subscriber->id,'name'=>$subscriber->name,'email'=>$subscriber->email,'token'=>$subscriber->token,'state'=>0,'attempts'=>0,'error'=>''];$db->insertObject('#__academy_mail_queue',$queue);}$app->enqueueMessage(($campaignState===2?'Campaign scheduled':'Campaign queued').' for '.count($subscribers).' active subscriber(s).');$this->redirectToCampaign((int)$campaign->id);}
public function test():void{Session::checkToken()or jexit('Invalid token');$this->allowed();$app=Factory::getApplication();$email=trim($app->getInput()->post->getString('test_email'))?:$app->getIdentity()->email;$subject=trim($app->getInput()->post->getString('subject'));$body=$app->getInput()->post->get('body','','raw');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$subject===''||trim(strip_tags($body))==='')throw new \RuntimeException('A valid test address, subject, and message are required.',400);$body=str_replace(['{name}','{email}','{unsubscribe_url}'],[$app->getIdentity()->name,$email,'#'],$body);(new CampaignMailer())->send($email,$app->getIdentity()->name,'[TEST] '.$subject,$body);$app->enqueueMessage('Test email sent to '.$email.'.');$this->redirect();}
public function send():void{Session::checkToken()or jexit('Invalid token');$this->allowed();$app=Factory::getApplication();$campaignId=$app->getInput()->post->getInt('campaign_id');$db=Factory::getContainer()->get(DatabaseInterface::class);$skip=$db->createQuery()->update('#__academy_mail_queue AS q')->set(['q.state=2','q.error='.$db->quote('Subscriber is no longer active.')])->where('q.state=0')->where('NOT EXISTS (SELECT 1 FROM #__academy_subscribers AS s WHERE s.id=q.subscriber_id AND s.state=1)');if($campaignId)$skip->where('q.campaign_id='.$campaignId);$db->setQuery($skip)->execute();$query=$db->createQuery()->select(['q.*','c.subject','c.body'])->from('#__academy_mail_queue AS q')->join('INNER','#__academy_campaigns AS c ON c.id=q.campaign_id')->join('INNER','#__academy_subscribers AS s ON s.id=q.subscriber_id AND s.state=1')->where('q.state=0')->where('c.state=0')->order('q.id');if($campaignId)$query->where('q.campaign_id='.$campaignId);$rows=$db->setQuery($query,0,25)->loadObjectList();$sent=0;$failed=0;$transport=new CampaignMailer();foreach($rows as $row){try{if(($row->tracking_token??'')===''){$row->tracking_token=bin2hex(random_bytes(24));$db->setQuery($db->createQuery()->update('#__academy_mail_queue')->set('tracking_token='.$db->quote($row->tracking_token))->where('id='.(int)$row->id))->execute();}$unsubscribe=Uri::root().'index.php?option=com_academy&task=engagement.unsubscribe&token='.rawurlencode($row->token);$body=str_replace(['{name}','{email}','{unsubscribe_url}'],[$row->name,$row->email,$unsubscribe],$row->body);$body=$this->addTracking($body,$row->tracking_token).'<p><a href="'.htmlspecialchars($unsubscribe,ENT_QUOTES,'UTF-8').'">Unsubscribe</a></p>';$transport->send($row->email,$row->name,$row->subject,$body);$state=1;$error='';$sent++;}catch(\Throwable $e){$state=-1;$error=substr($e->getMessage(),0,1000);$failed++;}$db->setQuery($db->createQuery()->update('#__academy_mail_queue')->set(['state='.$state,'attempts=attempts+1','error='.$db->quote($error)])->where('id='.(int)$row->id))->execute();}if($campaignId){$counts=$db->setQuery($db->createQuery()->select(['COALESCE(SUM(state=0),0) AS pending','COALESCE(SUM(state=-1),0) AS failed'])->from('#__academy_mail_queue')->where('campaign_id='.$campaignId))->loadObject();$campaignState=(int)$counts->pending?0:((int)$counts->failed?-1:1);$db->setQuery($db->createQuery()->update('#__academy_campaigns')->set('state='.$campaignState)->where('id='.$campaignId))->execute();}$app->enqueueMessage("Sent $sent; failed $failed.");$this->redirect($campaignId);}
private function addTracking(string $body,string $token):string{$params=ComponentHelper::getParams('com_academy');if($params->get('email_link_tracking',0)){$secret=(string)Factory::getApplication()->get('secret');$body=preg_replace_callback('#href=(["\'])(https?://[^"\']+)\1#i',static function(array $match)use($secret,$token):string{$encoded=rtrim(strtr(base64_encode(html_entity_decode($match[2],ENT_QUOTES|ENT_HTML5,'UTF-8')),'+/','-_'),'=');$signature=hash_hmac('sha256',$encoded.'|'.$token,$secret);$url=Uri::root().'index.php?option=com_academy&task=engagement.click&token='.rawurlencode($token).'&url='.rawurlencode($encoded).'&sig='.$signature;return 'href='.$match[1].htmlspecialchars($url,ENT_QUOTES,'UTF-8').$match[1];},$body);}if($params->get('email_open_tracking',0)){$pixel=Uri::root().'index.php?option=com_academy&task=engagement.open&token='.rawurlencode($token);$body.='<img src="'.htmlspecialchars($pixel,ENT_QUOTES,'UTF-8').'" alt="" width="1" height="1" style="display:none">';}return $body;}
public function retry():void{Session::checkToken()or jexit('Invalid token');$this->allowed();$app=Factory::getApplication();$campaignId=$app->getInput()->post->getInt('campaign_id');$db=Factory::getContainer()->get(DatabaseInterface::class);$query=$db->createQuery()->update('#__academy_mail_queue')->set(['state=0','error='.$db->quote('')])->where('state=-1');if($campaignId)$query->where('campaign_id='.$campaignId);$db->setQuery($query)->execute();$skip=$db->createQuery()->update('#__academy_mail_queue AS q')->set(['q.state=2','q.error='.$db->quote('Subscriber is no longer active.')])->where('q.state=0')->where('NOT EXISTS (SELECT 1 FROM #__academy_subscribers AS s WHERE s.id=q.subscriber_id AND s.state=1)');if($campaignId)$skip->where('q.campaign_id='.$campaignId);$db->setQuery($skip)->execute();if($campaignId)$db->setQuery($db->createQuery()->update('#__academy_campaigns')->set('state=0')->where('id='.$campaignId))->execute();$app->enqueueMessage('Failed messages for active subscribers returned to the queue.');$this->redirect($campaignId);}
public function state():void{Session::checkToken()or jexit('Invalid token');$this->allowed();$app=Factory::getApplication();$campaignId=$app->getInput()->post->getInt('campaign_id');$state=$app->getInput()->post->getInt('campaign_state');if(!$campaignId||!in_array($state,[0,3,4],true))throw new \RuntimeException('Invalid campaign action.',400);$db=Factory::getContainer()->get(DatabaseInterface::class);$db->setQuery($db->createQuery()->update('#__academy_campaigns')->set('state='.$state)->where('id='.$campaignId))->execute();if($state===4)$db->setQuery($db->createQuery()->update('#__academy_mail_queue')->set(['state=3','error='.$db->quote('Campaign canceled.')])->where('campaign_id='.$campaignId)->where('state=0'))->execute();$app->enqueueMessage($state===0?'Campaign resumed and ready to send.':($state===3?'Campaign paused.':'Campaign canceled.'));$this->redirect($campaignId);}
public function export():void{$this->allowed();$campaignId=Factory::getApplication()->getInput()->getInt('campaign_id');if(!$campaignId)throw new \RuntimeException('Campaign not found.',404);$db=Factory::getContainer()->get(DatabaseInterface::class);$campaign=$db->setQuery($db->createQuery()->select(['id','subject','created'])->from('#__academy_campaigns')->where('id='.$campaignId))->loadObject();if(!$campaign)throw new \RuntimeException('Campaign not found.',404);$rows=$db->setQuery($db->createQuery()->select(['name','email','state','attempts','error','opened_count','clicked_count','last_opened','last_clicked'])->from('#__academy_mail_queue')->where('campaign_id='.$campaignId)->order('id'))->loadAssocList();$app=Factory::getApplication();$app->setHeader('Content-Type','text/csv; charset=utf-8',true);$app->setHeader('Content-Disposition','attachment; filename="academy-campaign-'.$campaignId.'.csv"',true);$app->sendHeaders();$output=fopen('php://output','wb');fputcsv($output,['campaign_id','subject','created']);fputcsv($output,[$campaign->id,$campaign->subject,$campaign->created]);fputcsv($output,[]);fputcsv($output,['name','email','status','attempts','error','opens','clicks','last_opened','last_clicked']);$labels=[-1=>'failed',0=>'queued',1=>'sent',2=>'skipped',3=>'canceled'];foreach($rows as $row){$row['state']=$labels[(int)$row['state']]??'unknown';fputcsv($output,$row);}fclose($output);$app->close();}
}
